"""Shared validation helpers for the forest-controller service."""
import re

ID_RE = re.compile(r'\A[A-Za-z0-9_.-]{1,32}\Z')

LIM_TICK = 10 ** 12
LIM_RATE = 10 ** 12
LIM_CHUNK = 10 ** 12
LIM_PERIOD = 10 ** 6
LIM_REV = 10 ** 12
LIM_NODE = 47
LIM_LINK = 127
MAX_LINKS = 128
MAX_BOOKINGS = 128
MAX_ENV_TOTAL = 2048
MAX_ENV_ENTRIES = 128
MAX_AUDIT_TICKS = 8
MAX_EDIT_CHANGES = 128
MAX_PARTICIPANTS = 32
MIN_PARTICIPANTS = 2
MAX_LOAD_N = 48


class Invalid(Exception):
    """Raised for any schema / JSON level problem."""


def need(cond):
    if not cond:
        raise Invalid()


def is_int(x):
    return type(x) is int


def req_int(x, lo, hi):
    if type(x) is not int:
        raise Invalid()
    if x < lo or x > hi:
        raise Invalid()
    return x


def req_id(x):
    if type(x) is not str:
        raise Invalid()
    if not ID_RE.match(x):
        raise Invalid()
    return x


def req_exact_keys(obj, keys):
    """obj must be a JSON object with exactly the given set of keys."""
    if type(obj) is not dict:
        raise Invalid()
    if set(obj.keys()) != set(keys):
        raise Invalid()
    return obj


def req_list(x):
    if type(x) is not list:
        raise Invalid()
    return x


def req_bool(x):
    if type(x) is not bool:
        raise Invalid()
    return x


def req_window(x):
    """[s,e] with 0<=s<e<=10^12."""
    if type(x) is not list or len(x) != 2:
        raise Invalid()
    s = req_int(x[0], 0, LIM_TICK)
    e = req_int(x[1], 0, LIM_TICK)
    if s >= e:
        raise Invalid()
    return (s, e)


def req_envelope(x):
    """At most 128 distinct [link_id, rate] pairs, rate in [1,10^12].

    Returns a dict link_id -> rate.
    """
    if type(x) is not list:
        raise Invalid()
    if len(x) > MAX_ENV_ENTRIES:
        raise Invalid()
    out = {}
    for entry in x:
        if type(entry) is not list or len(entry) != 2:
            raise Invalid()
        l = req_int(entry[0], 0, LIM_LINK)
        b = req_int(entry[1], 1, LIM_RATE)
        if l in out:
            raise Invalid()
        out[l] = b
    return out


def sorted_ids(ids):
    return sorted(ids)
PYEOF
